package uy.utu.biblioteca;
import java.sql.*;import java.util.*;
public class AlumnoDAO implements Repository<Alumno>{
 public List<Alumno> listar(String f)throws SQLException{List<Alumno> out=new ArrayList<>();String q="SELECT id,nombre,documento,email,grupo FROM alumnos WHERE nombre LIKE ? OR documento LIKE ? OR grupo LIKE ? ORDER BY nombre";try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement(q)){String x="%"+(f==null?"":f.trim())+"%";for(int i=1;i<=3;i++)p.setString(i,x);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new Alumno(r.getInt("id"),r.getString("nombre"),r.getString("documento"),r.getString("email"),r.getString("grupo")));}}return out;}
 public void crear(Alumno a)throws SQLException{String q="INSERT INTO alumnos(nombre,documento,email,grupo) VALUES(?,?,?,?)";try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement(q)){p.setString(1,a.getNombre());p.setString(2,a.getDocumento());p.setString(3,a.getEmail());p.setString(4,a.getGrupo());p.executeUpdate();}}
 public void actualizar(Alumno a)throws SQLException{String q="UPDATE alumnos SET nombre=?,documento=?,email=?,grupo=? WHERE id=?";try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement(q)){p.setString(1,a.getNombre());p.setString(2,a.getDocumento());p.setString(3,a.getEmail());p.setString(4,a.getGrupo());p.setInt(5,a.getId());if(p.executeUpdate()==0)throw new SQLException("No existe el alumno indicado.");}}
 public void eliminar(int id)throws SQLException{try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement("DELETE FROM alumnos WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}
}
